# ---------------------------------------------------------------------------
# INV-001: Timeout Enforcement Tests
# ---------------------------------------------------------------------------

class TestInv001TimeoutEnforcement:
    """All external I/O must have explicit timeout ≤ 50ms."""

    async def test_io_timeout_constant_within_limit(self):
        """Verify the hard timeout constant is ≤ 50ms."""
        assert TELEMETRY_TIMEOUT_MS <= 50, "INV-001 violated: timeout exceeds 50ms"

    async def test_async_io_wrapper_enforces_timeout(self, engine):
        """Verify async I/O operations fail fast on timeout."""
        slow_io = AsyncMock(side_effect=asyncio.TimeoutError)

        with pytest.raises(asyncio.TimeoutError):
            await asyncio.wait_for(slow_io(), timeout=TELEMETRY_TIMEOUT_MS / 1000)

        elapsed = time.monotonic()
        try:
            await asyncio.wait_for(slow_io(), timeout=TELEMETRY_TIMEOUT_MS / 1000)
        except asyncio.TimeoutError:
            pass
        elapsed = time.monotonic() - elapsed
        assert elapsed <= 0.1, f"Timeout took {elapsed:.3f}s, expected ≤ 0.1s"

    async def test_engine_io_methods_have_timeout_parameter(self, engine):
        """All public I/O methods must accept a timeout parameter."""
        import inspect
        for method_name in ["ingest_sensor_data", "process_telemetry_packet", "fetch_external_context"]:
            method = getattr(engine, method_name, None)
            if method is None:
                continue
            sig = inspect.signature(method)
            assert "timeout" in sig.parameters, f"{method_name} missing timeout parameter"


