class TestInv002BoundedMemory:
    """No unbounded memory allocation per sensor stream."""

    async def test_sensor_history_ring_buffer_bounded(self, engine):
        """Verify history deque never exceeds MAX_SENSOR_HISTORY."""
        # Simulate massive ingestion
        for i in range(MAX_SENSOR_HISTORY * 3):
            await engine.ingest_sensor_data(
                sensor_id=f"SENSOR-{i % 10}",
                sensor_type=SensorType.VIBRATION,
                value=float(i),
                timestamp=time.time(),
            )

        for sensor_id, history in engine._sensor_histories.items():
            assert len(history) <= MAX_SENSOR_HISTORY, f"History for {sensor_id} exceeded bound"

    async def test_ring_buffer_eviction_order(self, engine):
        """Verify oldest entries are evicted first (FIFO)."""
        sensor_id = "VIB-EVICT"
        for i in range(MAX_SENSOR_HISTORY + 10):
            await engine.ingest_sensor_data(
                sensor_id=sensor_id,
                sensor_type=SensorType.VIBRATION,
                value=float(i),
                timestamp=time.time(),
            )

        history = engine._sensor_histories[sensor_id]
        # First 10 entries should be evicted
        assert history[0].value == 10.0, "Oldest entries not evicted"
        assert history[-1].value == float(MAX_SENSOR_HISTORY + 9), "Newest entry missing"

    async def test_no_unbounded_global_structures(self, engine):
        """Verify no global dict/list grows without bound."""
        # Ingest from many sensors
        for i in range(MAX_CONCURRENT_SENSORS * 2):
            await engine.ingest_sensor_data(
                sensor_id=f"SENSOR-{i}",
                sensor_type=SensorType.RPM,
                value=float(i),
                timestamp=time.time(),
            )

        # Verify sensor registry is bounded
        assert len(engine._sensor_histories) <= MAX_CONCURRENT_SENSORS * 2, "Sensor registry unbounded"


