class TestInv003LockProtection:
    """All state mutations must be protected by asyncio.Lock."""

    async def test_engine_has_lock(self, engine):
        """Engine must expose a lock for state protection."""
        assert hasattr(engine, "_state_lock"), "Engine missing state lock"
        assert isinstance(engine._state_lock, asyncio.Lock), "State lock is not asyncio.Lock"

    async def test_concurrent_mutations_are_serialized(self, engine):
        """Concurrent writes must not corrupt state."""
        sensor_id = "CONCURRENT-001"

        async def writer(value: float):
            await engine.ingest_sensor_data(
                sensor_id=sensor_id,
                sensor_type=SensorType.THERMAL,
                value=value,
                timestamp=time.time(),
            )

        # Fire 100 concurrent writes
        await asyncio.gather(*[writer(float(i)) for i in range(100)])

        history = engine._sensor_histories[sensor_id]
        assert len(history) == 100, "Lost updates under concurrency"
        # Verify all values present (no corruption)
        values = sorted([entry.value for entry in history])
        assert values == list(range(100)), "State corruption detected"

    async def test_lock_held_during_mutation(self, engine):
        """Verify lock is acquired during state-changing operations."""
        with patch.object(engine._state_lock, "acquire", wraps=engine._state_lock.acquire) as mock_acquire:
            await engine.ingest_sensor_data(
                sensor_id="LOCK-TEST",
                sensor_type=SensorType.RPM,
                value=1.0,
                timestamp=time.time(),
            )
            mock_acquire.assert_called_once(), "Lock not acquired during mutation"


