class TestPerformance:
    """Performance characteristics validation."""

    async def test_ingestion_latency_within_budget(self, engine):
        """Single ingestion must complete within 5ms."""
        start = time.perf_counter()
        for _ in range(100):
            await engine.ingest_sensor_data(
                sensor_id="PERF-001",
                sensor_type=SensorType.RPM,
                value=1.0,
                timestamp=time.time(),
            )
        elapsed = (time.perf_counter() - start) / 100
        assert elapsed < 0.005, f"Average ingestion latency {elapsed*1000:.2f}ms exceeds 5ms"

    async def test_throughput_meets_spec(self, engine):
        """Engine must handle ≥1000 ops/sec."""
        start = time.perf_counter()
        count = 0
        while time.perf_counter() - start < 1.0 and count < 5000:
            await engine.ingest_sensor_data(
                sensor_id="THROUGHPUT",
                sensor_type=SensorType.VIBRATION,
                value=float(count),
                timestamp=time.time(),
            )
            count += 1
        elapsed = time.perf_counter() - start
        throughput = count / elapsed
        assert throughput >= 1000, f"Throughput {throughput:.0f} ops/sec below 1000"


