class TestPropertyBased:
    """Property-based testing for invariants."""

    async def test_ring_buffer_size_invariant(self, engine):
        """For any number of ingestions, history size ≤ MAX_SENSOR_HISTORY."""
        import random
        sensor_id = "PROP-001"
        for _ in range(random.randint(1, MAX_SENSOR_HISTORY * 2)):
            await engine.ingest_sensor_data(
                sensor_id=sensor_id,
                sensor_type=SensorType.VIBRATION,
                value=random.random(),
                timestamp=time.time(),
            )
        assert len(engine._sensor_histories[sensor_id]) <= MAX_SENSOR_HISTORY

    async def test_timestamp_monotonicity(self, engine):
        """Ingested timestamps must be non-decreasing per sensor."""
        sensor_id = "MONO-001"
        last_ts = 0
        for i in range(100):
            ts = time.time()
            assert ts >= last_ts, "System clock went backwards"
            last_ts = ts
            await engine.ingest_sensor_data(
                sensor_id=sensor_id,
                sensor_type=SensorType.THERMAL,
                value=float(i),
                timestamp=ts,
            )

    async def test_hmac_signature_deterministic(self, engine):
        """Same payload must produce same signature."""
        payload = {"sensor_id": "DET-001", "value": 1.0}
        payload_bytes = json.dumps(payload, sort_keys=True).encode()
        sig1 = hmac.new(HMAC_SECRET, payload_bytes, hashlib.sha256).hexdigest()
        sig2 = hmac.new(HMAC_SECRET, payload_bytes, hashlib.sha256).hexdigest()
        assert sig1 == sig2, "HMAC signature not deterministic"


