class TestIntegration:
    """End-to-end integration scenarios."""

    async def test_full_pipeline(self, engine):
        """Complete pipeline: ingest → detect → predict → act."""
        sensor_id = "INTEGRATION-001"

        # Phase 1: Normal operation
        for i in range(100):
            await engine.ingest_sensor_data(
                sensor_id=sensor_id,
                sensor_type=SensorType.RPM,
                value=100.0 - (i * 0.1),  # Gradual degradation
                timestamp=time.time(),
            )

        # Phase 2: Anomaly detection
        await engine.ingest_sensor_data(
            sensor_id=sensor_id,
            sensor_type=SensorType.RPM,
            value=5.0,  # Critical drop
            timestamp=time.time(),
        )
        anomalies = await engine.get_recent_anomalies(sensor_id)
        assert len(anomalies) > 0, "Anomaly not detected in pipeline"

        # Phase 3: TTF prediction
        prediction = await engine.predict_ttf(sensor_id)
        assert prediction is not None, "TTF prediction failed in pipeline"

        # Phase 4: Safety action
        safety_action = await engine.execute_safety_protocol(sensor_id)
        assert safety_action is not None, "Safety protocol failed"

    async def test_multi_sensor_coordination(self, engine):
        """Multiple sensors must coordinate without interference."""
        sensors = [f"SENSOR-{i}" for i in range(10)]

        # Ingest from all sensors concurrently
        async def ingest_all():
            for sensor_id in sensors:
                await engine.ingest_sensor_data(
                    sensor_id=sensor_id,
                    sensor_type=SensorType.VIBRATION,
                    value=1.0,
                    timestamp=time.time(),
                )

        await asyncio.gather(*[ingest_all() for _ in range(10)])

        # Verify all sensors have data
        for sensor_id in sensors:
            assert sensor_id in engine._sensor_histories, f"Missing data for {sensor_id}"
            assert len(engine._sensor_histories[sensor_id]) == 10, f"Incomplete data for {sensor_id}"


